package bmmgen

import (
	"bytes"
	"fmt"
	"go/format"
	"path/filepath"
)

// releaseFileName is the generated file that carries the RM release constant,
// written into the RM target package beside the per-package files.
const releaseFileName = "release_gen.go"

// RenderReleaseFile produces `openehr/rm/release_gen.go`: the root schema's
// `rm_release` as the exported constant `Release`. The SDK writes that value
// into ARCHETYPED.rm_version wherever it builds an ARCHETYPED itself, so it
// has to come from the schema the package is generated from, not from a
// literal in hand-written code.
//
// Returns nil for any target other than RM: the AOM 1.4 target has no RM
// release of its own. A root schema that declares no `rm_release` is an error,
// because an empty constant would write an ARCHETYPED the RM floor rejects.
func RenderReleaseFile(plan *Plan) ([]byte, error) {
	if plan.Target.GoPackage != "rm" {
		return nil, nil
	}
	if plan.Schema == nil || plan.Schema.RMRelease == "" {
		return nil, fmt.Errorf("bmmgen: root schema %q declares no rm_release", plan.Target.RootID)
	}

	var body bytes.Buffer
	body.WriteString("// Code generated by bmmgen; DO NOT EDIT.\n")
	fmt.Fprintf(&body, "// Source: %s\n\n", plan.Target.SourceLabel)
	fmt.Fprintf(&body, "package %s\n\n", plan.Target.GoPackage)
	body.WriteString("// Release is the openEHR Reference Model release this package is\n")
	body.WriteString("// generated from. The SDK writes it into ARCHETYPED.rm_version wherever\n")
	body.WriteString("// it builds an ARCHETYPED itself, for example when it decodes a FLAT or\n")
	body.WriteString("// STRUCTURED composition or generates an instance from a template.\n")
	fmt.Fprintf(&body, "const Release = %q\n", plan.Schema.RMRelease)
	formatted, err := format.Source(body.Bytes())
	if err != nil {
		return body.Bytes(), fmt.Errorf("gofmt %s: %w", releaseFileName, err)
	}
	return formatted, nil
}

// emitReleaseFile renders the release file for plan and writes it into outDir,
// or, in verify mode, records drift against what is on disk. It is a no-op for
// a target [RenderReleaseFile] does not emit for.
func emitReleaseFile(opts Options, plan *Plan, outDir string, tr *TargetResult, result *Result) error {
	body, err := RenderReleaseFile(plan)
	if err != nil || body == nil {
		return err
	}
	path := filepath.Join(outDir, releaseFileName)
	tr.Files = append(tr.Files, path)
	result.Files = append(result.Files, path)
	if opts.Verify {
		drift, err := compareFile(path, body)
		if err != nil {
			return err
		}
		if drift != nil {
			result.Drifts = append(result.Drifts, *drift)
		}
		return nil
	}
	return writeAtomic(path, body)
}
